877:   function scheduleClick(time, accented) {
878:     if (!state.audio || state.audio.state !== 'running') return;
879:     try {
880:       const oscillator = state.audio.createOscillator();
881:       const gain = state.audio.createGain();
882:       const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
883:       oscillator.type = 'sine';
884:       oscillator.frequency.value = accented ? 880 : 590;
885:       gain.gain.setValueAtTime(0.0001, start);
886:       gain.gain.exponentialRampToValueAtTime(accented ? 0.11 : 0.055, start + 0.004);
887:       gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.045);
888:       oscillator.connect(gain);
889:       gain.connect(state.audio.destination);
890:       oscillator.start(start);
891:       oscillator.stop(start + 0.05);
892:       oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
893:     } catch (_) {
894:       // A missed sound must not stop the visual beat scheduler.
895:     }
896:   }
