924:   function parseYouTubeUrl(value) {
925:     const raw = String(value || '').trim();
926:     if (!raw || raw.length > 2048) return null;
927:     let url;
928:     try {
929:       url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
930:     } catch (_) {
931:       return null;
932:     }
933:     if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
934:     const host = url.hostname.toLowerCase().replace(/\.$/, '');
935:     const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
936:     const isShort = host === 'youtu.be';
937:     if (!isYoutube && !isShort) return null;
938:     const playlistId = url.searchParams.get('list');
939:     const validPlaylist = playlistId && /^[A-Za-z0-9_-]{10,120}$/.test(playlistId);
940:     let videoId = '';
941:     if (isShort) videoId = url.pathname.split('/').filter(Boolean)[0] || '';
942:     else if (url.pathname === '/watch') videoId = url.searchParams.get('v') || '';
943:     else {
944:       const match = url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})(?:\/|$)/);
945:       if (match) videoId = match[1];
946:     }
947:     if (/^[A-Za-z0-9_-]{11}$/.test(videoId)) return { type: 'video', id: videoId };
948:     if (validPlaylist) return { type: 'playlist', id: playlistId };
949:     return null;
950:   }
