952:   function loadYouTubeApi() {
953:     if (window.YT && window.YT.Player) {
954:       createYouTubePlayer();
955:       return;
956:     }
957:     if (state.apiState === 'loading') return;
958:     state.apiState = 'loading';
959:     const previousCallback = window.onYouTubeIframeAPIReady;
960:     window.onYouTubeIframeAPIReady = () => {
961:       if (typeof previousCallback === 'function') {
962:         try { previousCallback(); } catch (_) { /* Do not block this player. */ }
963:       }
964:       state.apiState = 'ready';
