  state.lastTickNumber = -1;
  state.lastTickAt = null;
  state.clockStepMs = clockGrid(0).stepMs;
  state.nextTickAt = performance.now() + 70;
  state.barNumber = 0;
  updateBarUI();
  scheduleLoop(state.generation);
}

