    }
  }

  function closeYouTubePlayer() {
    if (state.player) {
      try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
    }
    state.player = null;
    state.pendingMedia = null;
    ui.player.replaceChildren();
